-- AI/ML pathway ("Cipher Division") Act 17 -- "TensorFlow Engine" content.
-- Second World of Arc III ("Neural Systems", Acts 13-18). Introduces Noah
-- Kim, ML Platform Engineer, in his first speaking appearance. 1 campaign,
-- 2 operations, 12 missions (11 lessons + boss), following the same
-- campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as every other Act. The world row
-- (world-ai-tensorflow-engine) already exists; only its child content is
-- inserted here.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-ai-tensorflow-engine', 'world-ai-tensorflow-engine', 'tensorflow-engine', '17A - TensorFlow Engine', 'Learn TensorFlow and Keras end to end -- tensors, Sequential and Functional models, tf.data, losses, optimizers, metrics, callbacks and checkpoints -- while Noah Kim pushes Cipher Division to answer a question research alone never had to: which framework actually ships.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-ai-tensorflow-engine-1', 'campaign-ai-tensorflow-engine', 'the-other-toolkit', 'The Other Toolkit', 'Tensors, Keras, Sequential, the Functional API, tf.data and losses -- the core vocabulary of building a model in TensorFlow.', 1),
  ('operation-ai-tensorflow-engine-2', 'campaign-ai-tensorflow-engine', 'a-fair-comparison', 'A Fair Comparison', 'Optimizers, metrics, callbacks, checkpoints and a hand-written training loop, assembled into a TensorFlow model judged against its PyTorch twin under a genuinely controlled comparison.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-ai-tensorflow-engine-01', 'world-ai-tensorflow-engine', 'campaign-ai-tensorflow-engine', 'operation-ai-tensorflow-engine-1', 'tensorflow-tensors', 'TensorFlow Tensors', 'Noah Kim arrives asking the question nobody in Cipher Division has bothered to ask yet: which framework are we actually going to run in production, and why.', 'beginner', ARRAY['maya','noah'], null, null, '{"type":"simulation","simulationId":"tensorflow-tensors-sim"}'::jsonb, '{"xp":330,"credits":80}'::jsonb, false, 1),
  ('mission-ai-tensorflow-engine-02', 'world-ai-tensorflow-engine', 'campaign-ai-tensorflow-engine', 'operation-ai-tensorflow-engine-1', 'keras', 'Keras', 'TensorFlow used to be two separate projects. Now Keras is simply how anyone builds a model in it.', 'beginner', ARRAY['noah'], '{"requiredMissionIds":["mission-ai-tensorflow-engine-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"keras-sim"}'::jsonb, '{"xp":340,"credits":80}'::jsonb, false, 2),
  ('mission-ai-tensorflow-engine-03', 'world-ai-tensorflow-engine', 'campaign-ai-tensorflow-engine', 'operation-ai-tensorflow-engine-1', 'sequential', 'Sequential', 'The simplest way to stack layers in Keras, and the first place a wrong output activation quietly breaks a classifier.', 'beginner', ARRAY['noah'], '{"requiredMissionIds":["mission-ai-tensorflow-engine-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"sequential-sim"}'::jsonb, '{"xp":340,"credits":85}'::jsonb, false, 3),
  ('mission-ai-tensorflow-engine-04', 'world-ai-tensorflow-engine', 'campaign-ai-tensorflow-engine', 'operation-ai-tensorflow-engine-1', 'functional-api', 'Functional API', 'Every layer becomes a callable and the graph gets wired by hand -- the API for anything Sequential cannot express.', 'intermediate', ARRAY['noah'], '{"requiredMissionIds":["mission-ai-tensorflow-engine-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"functional-api-sim"}'::jsonb, '{"xp":350,"credits":85}'::jsonb, false, 4),
  ('mission-ai-tensorflow-engine-05', 'world-ai-tensorflow-engine', 'campaign-ai-tensorflow-engine', 'operation-ai-tensorflow-engine-1', 'tf-data', 'tf.data', 'Raw arrays do not feed a model efficiently at scale. tf.data is the pipeline that keeps data moving instead of blocking training.', 'intermediate', ARRAY['noah','byte'], '{"requiredMissionIds":["mission-ai-tensorflow-engine-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"tf-data-sim"}'::jsonb, '{"xp":350,"credits":85}'::jsonb, false, 5),
  ('mission-ai-tensorflow-engine-06', 'world-ai-tensorflow-engine', 'campaign-ai-tensorflow-engine', 'operation-ai-tensorflow-engine-1', 'losses', 'Losses', 'The one number training actually optimizes -- and the easiest place to quietly solve the wrong problem.', 'intermediate', ARRAY['noah'], '{"requiredMissionIds":["mission-ai-tensorflow-engine-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"losses-sim"}'::jsonb, '{"xp":360,"credits":90}'::jsonb, false, 6),
  ('mission-ai-tensorflow-engine-07', 'world-ai-tensorflow-engine', 'campaign-ai-tensorflow-engine', 'operation-ai-tensorflow-engine-2', 'optimizers', 'Optimizers', 'The loss says how wrong the model is. The optimizer decides what to do about it.', 'intermediate', ARRAY['noah'], '{"requiredMissionIds":["mission-ai-tensorflow-engine-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"optimizers-sim"}'::jsonb, '{"xp":360,"credits":90}'::jsonb, false, 7),
  ('mission-ai-tensorflow-engine-08', 'world-ai-tensorflow-engine', 'campaign-ai-tensorflow-engine', 'operation-ai-tensorflow-engine-2', 'metrics', 'Metrics', 'Loss drives training. Metrics are what a human actually reads to know if the model is any good.', 'intermediate', ARRAY['noah'], '{"requiredMissionIds":["mission-ai-tensorflow-engine-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"metrics-sim"}'::jsonb, '{"xp":370,"credits":90}'::jsonb, false, 8),
  ('mission-ai-tensorflow-engine-09', 'world-ai-tensorflow-engine', 'campaign-ai-tensorflow-engine', 'operation-ai-tensorflow-engine-2', 'callbacks', 'Callbacks', 'Functions Keras calls automatically during training, so nobody has to babysit a run by hand in production.', 'intermediate', ARRAY['noah','byte'], '{"requiredMissionIds":["mission-ai-tensorflow-engine-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"callbacks-sim"}'::jsonb, '{"xp":370,"credits":95}'::jsonb, false, 9),
  ('mission-ai-tensorflow-engine-10', 'world-ai-tensorflow-engine', 'campaign-ai-tensorflow-engine', 'operation-ai-tensorflow-engine-2', 'checkpoints', 'Checkpoints', 'Saving a model mid-run, not just at the end -- protection against crashes, interruptions, and overfitting past the best epoch.', 'intermediate', ARRAY['noah'], '{"requiredMissionIds":["mission-ai-tensorflow-engine-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"checkpoints-sim"}'::jsonb, '{"xp":380,"credits":95}'::jsonb, false, 10),
  ('mission-ai-tensorflow-engine-11', 'world-ai-tensorflow-engine', 'campaign-ai-tensorflow-engine', 'operation-ai-tensorflow-engine-2', 'custom-training', 'Custom Training', 'When model.fit() is not enough: a training loop written by hand with tf.GradientTape, one gradient step at a time.', 'intermediate', ARRAY['noah','byte'], '{"requiredMissionIds":["mission-ai-tensorflow-engine-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"custom-training-sim"}'::jsonb, '{"xp":380,"credits":95}'::jsonb, false, 11),
  ('mission-ai-tensorflow-engine-12', 'world-ai-tensorflow-engine', 'campaign-ai-tensorflow-engine', 'operation-ai-tensorflow-engine-2', 'two-frameworks-one-model', 'Two Frameworks, One Model', 'Retrain the same model in TensorFlow, under a comparison controlled tightly enough that the result actually means something.', 'boss', ARRAY['maya','noah','byte','elena'], '{"requiredMissionIds":["mission-ai-tensorflow-engine-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"two-frameworks-one-model-boss-sim"}'::jsonb, '{"xp":880,"credits":195,"badgeIds":["two-frameworks-one-model"],"skillXp":{"tensorflow":55,"ai_ml_fundamentals":20}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-ai-tensorflow-engine-01', 1, 'maya', 'Team, before we go further, meet Noah Kim. He is joining Cipher Division from the platform side -- the part of this operation that has to keep whatever research builds actually running once it ships.'),
  ('mission-ai-tensorflow-engine-01', 2, 'noah', 'Good to be here. I read the debrief from PyTorch Forge on the way in, and I want to ask the question nobody in this room has asked yet: which framework are we actually going to run in production, and why?'),
  ('mission-ai-tensorflow-engine-01', 3, 'noah', 'That is not a question about which one wins some benchmark. It is a question about what we are deploying to, who is already on this team, and what tooling already exists around it. TensorFlow answers that differently than PyTorch does.'),
  ('mission-ai-tensorflow-engine-01', 4, 'noah', 'So here is what we are going to do. Same model, same data, same evaluation, rebuilt in TensorFlow. If it lands in the same place as the PyTorch version, the framework was never the deciding factor. Let us find out.'),

  ('mission-ai-tensorflow-engine-02', 1, 'noah', 'TensorFlow used to be a low-level graph library with Keras sitting on top of it as a separate project. They merged years ago, and tf.keras is now the only way anyone actually builds a model in TensorFlow.'),
  ('mission-ai-tensorflow-engine-02', 2, 'noah', 'It is not a rival framework. It is the same relationship torch.nn has to raw PyTorch tensor operations -- a high-level API for defining, training and evaluating models, sitting on top of TensorFlow tensors and automatic differentiation.'),
  ('mission-ai-tensorflow-engine-02', 3, 'noah', 'You will barely touch anything below Keras in this Act. That is by design. The framework question was never about which one makes you write more boilerplate.'),

  ('mission-ai-tensorflow-engine-03', 1, 'noah', 'Simplest way to build a model in Keras: Sequential. Stack layers in order, data flows straight through from the first to the last, no branching.'),
  ('mission-ai-tensorflow-engine-03', 2, 'noah', 'Good fit for a plain feedforward network. Bad fit the moment a model needs two inputs, two outputs, or a layer whose output has to feed more than one place.'),
  ('mission-ai-tensorflow-engine-03', 3, 'noah', 'The classifier Cipher Division built in PyTorch Forge is a plain feedforward network. Sequential should reproduce it cleanly -- if it gets wired correctly.'),

  ('mission-ai-tensorflow-engine-04', 1, 'noah', 'Functional API is Sequential with the restriction removed. Every layer becomes a callable, applied directly to a tensor, and you wire the graph yourself.'),
  ('mission-ai-tensorflow-engine-04', 2, 'noah', 'That is what lets a model take two inputs, merge two branches back together, or reuse the same layer twice. Sequential cannot express any of that.'),
  ('mission-ai-tensorflow-engine-04', 3, 'noah', 'It reads almost the same as Sequential once you have seen it. The difference is entirely in what shape of network it can represent.'),

  ('mission-ai-tensorflow-engine-05', 1, 'noah', 'Raw arrays do not feed a model efficiently at scale. tf.data.Dataset is TensorFlow''s pipeline: load, transform, batch and prefetch data, overlapped with training instead of blocking it.'),
  ('mission-ai-tensorflow-engine-05', 2, 'byte', 'Training data for Cipher Division is already loaded as tensors. Turning it into a proper tf.data pipeline is the next step before anything trains.'),
  ('mission-ai-tensorflow-engine-05', 3, 'noah', 'Order matters more than people expect. Shuffle before you batch, not after, or you are only shuffling the order of whole batches instead of individual examples.'),

  ('mission-ai-tensorflow-engine-06', 1, 'noah', 'A loss function is the one number training actually optimizes. Pick the wrong one for the task and the model can train perfectly and still be solving the wrong problem.'),
  ('mission-ai-tensorflow-engine-06', 2, 'noah', 'Binary classification wants binary crossentropy. Multi-class with one-hot labels wants categorical crossentropy. Multi-class with plain integer labels wants sparse categorical crossentropy. Regression usually wants mean squared error.'),
  ('mission-ai-tensorflow-engine-06', 3, 'noah', 'That distinction between categorical and sparse categorical trips up more production code than anything else in this mission. Watch for it.'),

  ('mission-ai-tensorflow-engine-07', 1, 'noah', 'The optimizer decides how the weights actually move once a gradient is computed. The loss says how wrong you are. The optimizer decides what to do about it.'),
  ('mission-ai-tensorflow-engine-07', 2, 'noah', 'Adam is the default nearly everyone reaches for first -- it adapts its own learning rate per parameter and gets a model training reasonably well with little tuning. Plain SGD needs more hand-holding but can generalize better once tuned.'),
  ('mission-ai-tensorflow-engine-07', 3, 'noah', 'Learning rate is the one knob that breaks more training runs than any architecture choice. Too high and loss oscillates or diverges. Too low and training barely moves.'),

  ('mission-ai-tensorflow-engine-08', 1, 'noah', 'Loss and metrics are not the same job. Loss has to be differentiable, because gradients are computed from it. Metrics do not -- they exist purely for a human to read.'),
  ('mission-ai-tensorflow-engine-08', 2, 'noah', 'Accuracy, precision, recall, AUC -- pick metrics that actually match what the model needs to be good at, not just whatever Keras lists first.'),
  ('mission-ai-tensorflow-engine-08', 3, 'noah', 'A model can have a shrinking loss and a metric that tells a completely different story. When that happens, believe the metric that matches what you actually care about.'),

  ('mission-ai-tensorflow-engine-09', 1, 'noah', 'A callback is a function Keras calls automatically at specific points during training -- end of an epoch, end of a batch, start of training. Nobody should be babysitting a training loop by hand in production.'),
  ('mission-ai-tensorflow-engine-09', 2, 'byte', 'EarlyStopping, ModelCheckpoint, ReduceLROnPlateau -- I have seen all three across Cipher Labs systems already. This is standard production discipline, not a TensorFlow-specific trick.'),
  ('mission-ai-tensorflow-engine-09', 3, 'noah', 'The one mistake I see constantly: monitoring training loss instead of validation loss. Training loss will happily keep improving long after the model has started overfitting.'),

  ('mission-ai-tensorflow-engine-10', 1, 'noah', 'A checkpoint saves a model''s weights during training, not just at the end. Long runs crash, get interrupted, or overfit after their best epoch -- checkpoints protect against all three.'),
  ('mission-ai-tensorflow-engine-10', 2, 'noah', 'save_best_only watches a metric and keeps only the checkpoint where that metric was at its best, discarding the rest. Get the monitored direction wrong -- min instead of max, or the reverse -- and it quietly keeps the worst model instead.'),
  ('mission-ai-tensorflow-engine-10', 3, 'noah', 'This is not academic. This is exactly how a production model gets deployed: from a checkpoint, not from whatever happened to be in memory when a run ended.'),

  ('mission-ai-tensorflow-engine-11', 1, 'noah', 'model.fit() covers most cases. It does not cover everything -- custom losses that need extra state, multiple models trained together, anything with logic Keras never anticipated. That is when you write the training loop yourself.'),
  ('mission-ai-tensorflow-engine-11', 2, 'noah', 'tf.GradientTape records every operation performed on a trainable tensor while it is open. Run the forward pass and compute the loss inside that block, and you can ask the tape for gradients afterward.'),
  ('mission-ai-tensorflow-engine-11', 3, 'byte', 'Miss that step -- run the forward pass outside the tape -- and the tape records nothing. Gradients come back as None, silently, no error thrown.'),
  ('mission-ai-tensorflow-engine-11', 4, 'noah', 'Then optimizer.apply_gradients does the update itself, using whatever apply_gradients would have done inside model.fit() automatically. Same math, just spelled out by hand.'),

  ('mission-ai-tensorflow-engine-12', 1, 'maya', 'The TensorFlow model is trained. Before anyone treats this as a real answer, Cipher Division judges it the same way it judges anything else: on evidence, not on which framework people prefer.'),
  ('mission-ai-tensorflow-engine-12', 2, 'noah', 'Fair means three things held constant: the same architecture and parameter count as the PyTorch version, the same data splits and hyperparameters, and the same evaluation protocol -- not a friendlier test set.'),
  ('mission-ai-tensorflow-engine-12', 3, 'elena', 'For the record, the PyTorch model from the earlier run is not going anywhere. I am not here to defend it. I am here so there is an actual second data point to compare against, not just a claim.'),
  ('mission-ai-tensorflow-engine-12', 4, 'byte', 'Both training runs and both evaluation reports are loaded. I will not tell you which one is which until the numbers are actually judged on their own.'),
  ('mission-ai-tensorflow-engine-12', 5, 'noah', 'Whatever the numbers say, here is what I already know: if the two models land in the same place, the decision was never about accuracy. It comes down to what our team already knows, what we are deploying to, and what already exists around each ecosystem.'),
  ('mission-ai-tensorflow-engine-12', 6, 'maya', 'Then let us find out whether they actually land in the same place, or whether one of these comparisons is not as fair as it looks.'),
  ('mission-ai-tensorflow-engine-12', 7, 'byte', 'Both evaluation reports check out. TensorFlow model: same test accuracy, same loss curve shape, within noise of the PyTorch run.'),
  ('mission-ai-tensorflow-engine-12', 8, 'noah', 'Two frameworks, two equally good models, and Cipher Division still has not asked the harder question: whether either one was actually trained and evaluated the right way, or just trained twice the same wrong way.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-ai-tensorflow-engine-01-o1', 'mission-ai-tensorflow-engine-01', 1, 'Meet Noah Kim', 'Confirm you are ready to work with Cipher Division''s newest platform engineer.'),
  ('mission-ai-tensorflow-engine-01-o2', 'mission-ai-tensorflow-engine-01', 2, 'Translate the toolkit', 'Match each PyTorch tensor concept to its TensorFlow equivalent.'),

  ('mission-ai-tensorflow-engine-02-o1', 'mission-ai-tensorflow-engine-02', 1, 'Place Keras in the stack', 'Identify what Keras actually is relative to TensorFlow.'),
  ('mission-ai-tensorflow-engine-02-o2', 'mission-ai-tensorflow-engine-02', 2, 'Read a layer definition', 'State what a Dense layer definition actually configures.'),

  ('mission-ai-tensorflow-engine-03-o1', 'mission-ai-tensorflow-engine-03', 1, 'Fix the output layer', 'Find the bug in a Sequential classifier meant to output class probabilities.'),
  ('mission-ai-tensorflow-engine-03-o2', 'mission-ai-tensorflow-engine-03', 2, 'Know what Sequential cannot do', 'State what the Functional API can do that Sequential cannot.'),

  ('mission-ai-tensorflow-engine-04-o1', 'mission-ai-tensorflow-engine-04', 1, 'Wire the graph correctly', 'Find where a Functional API model fails to combine two branches.'),
  ('mission-ai-tensorflow-engine-04-o2', 'mission-ai-tensorflow-engine-04', 2, 'Know the Input tensor', 'State what tf.keras.Input actually creates.'),

  ('mission-ai-tensorflow-engine-05-o1', 'mission-ai-tensorflow-engine-05', 1, 'Fix the pipeline order', 'Find the tf.data call that is out of order.'),
  ('mission-ai-tensorflow-engine-05-o2', 'mission-ai-tensorflow-engine-05', 2, 'Know what prefetch does', 'State what .prefetch(tf.data.AUTOTUNE) actually does.'),

  ('mission-ai-tensorflow-engine-06-o1', 'mission-ai-tensorflow-engine-06', 1, 'Pick the right loss', 'Choose the loss that fits integer-labeled multi-class classification.'),
  ('mission-ai-tensorflow-engine-06-o2', 'mission-ai-tensorflow-engine-06', 2, 'Fix the mismatched loss', 'Find the line using the wrong loss for the labels this model was given.'),

  ('mission-ai-tensorflow-engine-07-o1', 'mission-ai-tensorflow-engine-07', 1, 'Know the optimizer''s job', 'State what an optimizer actually controls during training.'),
  ('mission-ai-tensorflow-engine-07-o2', 'mission-ai-tensorflow-engine-07', 2, 'Diagnose the learning rate', 'Diagnose a training run whose loss oscillates instead of converging.'),

  ('mission-ai-tensorflow-engine-08-o1', 'mission-ai-tensorflow-engine-08', 1, 'Separate loss from metrics', 'State the key difference between a loss function and a metric.'),
  ('mission-ai-tensorflow-engine-08-o2', 'mission-ai-tensorflow-engine-08', 2, 'Match each metric', 'Match each classification metric to what it actually measures.'),

  ('mission-ai-tensorflow-engine-09-o1', 'mission-ai-tensorflow-engine-09', 1, 'Fix EarlyStopping', 'Find the line that defeats the purpose of this EarlyStopping callback.'),
  ('mission-ai-tensorflow-engine-09-o2', 'mission-ai-tensorflow-engine-09', 2, 'Know what patience controls', 'State what the patience parameter actually controls.'),

  ('mission-ai-tensorflow-engine-10-o1', 'mission-ai-tensorflow-engine-10', 1, 'Fix the checkpoint direction', 'Find the line that keeps the worst-performing checkpoint instead of the best.'),
  ('mission-ai-tensorflow-engine-10-o2', 'mission-ai-tensorflow-engine-10', 2, 'Know why checkpoints matter', 'State why a long training run should be checkpointed, not just saved at the end.'),

  ('mission-ai-tensorflow-engine-11-o1', 'mission-ai-tensorflow-engine-11', 1, 'Fix the gradient tape', 'Find where a custom train_step fails to record the operations it needs gradients for.'),
  ('mission-ai-tensorflow-engine-11-o2', 'mission-ai-tensorflow-engine-11', 2, 'Know what the tape records', 'State what tf.GradientTape actually records.'),

  ('mission-ai-tensorflow-engine-12-o1', 'mission-ai-tensorflow-engine-12', 1, 'Confirm a fair build', 'Judge whether the TensorFlow model was actually built to match its PyTorch twin in architecture and capacity.'),
  ('mission-ai-tensorflow-engine-12-o2', 'mission-ai-tensorflow-engine-12', 2, 'Confirm a fair protocol', 'Judge whether the training and evaluation protocol was actually held constant across both frameworks.'),
  ('mission-ai-tensorflow-engine-12-o3', 'mission-ai-tensorflow-engine-12', 3, 'Name the real deciding factor', 'With performance equivalent, judge what should actually decide which framework Cipher Division standardizes on.'),
  ('mission-ai-tensorflow-engine-12-o4', 'mission-ai-tensorflow-engine-12', 4, 'State the verdict', 'Having judged the build, the protocol, and the real deciding factor, state Cipher Division''s verdict on TensorFlow versus PyTorch for this decision.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-ai-tensorflow-engine-01-o1-c1', 'mission-ai-tensorflow-engine-01-o1', 1, 'story_dialogue', 'Confirm you are ready to continue.', '{"lines":[{"characterId":"noah","text":"Ready to see what TensorFlow actually does differently, underneath the framework debate?"}]}'::jsonb, '{"acknowledged":true}'::jsonb),
  ('mission-ai-tensorflow-engine-01-o2-c1', 'mission-ai-tensorflow-engine-01-o2', 1, 'drag_and_drop', 'Match each PyTorch tensor concept to its TensorFlow equivalent.', '{"items":[{"id":"i1","text":"torch.tensor(data), a fixed array, with autograd tracked separately via requires_grad"},{"id":"i2","text":"A trainable parameter created with requires_grad=True"},{"id":"i3","text":"torch.zeros_like(x), a new tensor of zeros shaped like x"},{"id":"i4","text":"tensor.numpy(), pulling the underlying array out as NumPy"}],"targets":[{"id":"t1","label":"tf.constant(data), the fixed, non-trainable TensorFlow tensor type"},{"id":"t2","label":"tf.Variable(data, trainable=True), the trainable TensorFlow tensor type"},{"id":"t3","label":"tf.zeros_like(x)"},{"id":"t4","label":"tensor.numpy(), the identical method name in TensorFlow"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3","i4":"t4"}}'::jsonb),

  ('mission-ai-tensorflow-engine-02-o1-c1', 'mission-ai-tensorflow-engine-02-o1', 1, 'multiple_choice', 'What is Keras relative to TensorFlow?', '{"question":"What is Keras relative to TensorFlow?","options":[{"id":"a","text":"A separate framework that competes with TensorFlow"},{"id":"b","text":"The high-level API built into TensorFlow for defining, training and evaluating models"},{"id":"c","text":"A dataset-loading library with no connection to model building"},{"id":"d","text":"A visualization tool for training curves only"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-tensorflow-engine-02-o2-c1', 'mission-ai-tensorflow-engine-02-o2', 1, 'multiple_choice', 'A tf.keras.layers.Dense(64, activation="relu") layer definition mainly configures...', '{"question":"A tf.keras.layers.Dense(64, activation=\"relu\") layer definition mainly configures...","options":[{"id":"a","text":"The optimizer used during training"},{"id":"b","text":"How many neurons this layer has and what activation function it applies"},{"id":"c","text":"The loss function for the whole model"},{"id":"d","text":"How the dataset gets batched"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-tensorflow-engine-03-o1-c1', 'mission-ai-tensorflow-engine-03-o1', 1, 'code_debugging', 'Find the bug in this Sequential classifier meant to output probabilities across 10 classes.', '{"language":"python","code":"model = tf.keras.Sequential()\nmodel.add(tf.keras.layers.Dense(64, activation=\"relu\"))\nmodel.add(tf.keras.layers.Dense(32, activation=\"relu\"))\nmodel.add(tf.keras.layers.Dense(10, activation=\"relu\"))","question":"Which line stops this model from producing a valid probability distribution over 10 classes?"}'::jsonb, '{"requiredLineIds":["model.add(tf.keras.layers.Dense(10, activation=\"relu\"))"]}'::jsonb),
  ('mission-ai-tensorflow-engine-03-o2-c1', 'mission-ai-tensorflow-engine-03-o2', 1, 'multiple_choice', 'What can the Functional API do that Sequential cannot?', '{"question":"What can the Functional API do that Sequential cannot?","options":[{"id":"a","text":"Use activation functions"},{"id":"b","text":"Accept multiple inputs, produce multiple outputs, or reuse a layer in more than one place"},{"id":"c","text":"Use more than 10 layers"},{"id":"d","text":"Use Dense layers"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-tensorflow-engine-04-o1-c1', 'mission-ai-tensorflow-engine-04-o1', 1, 'code_debugging', 'This model was meant to combine two branches before its output layer. Find where that step went missing.', '{"language":"python","code":"inputs = tf.keras.Input(shape=(20,))\nbranch_a = tf.keras.layers.Dense(64, activation=\"relu\")(inputs)\nbranch_b = tf.keras.layers.Dense(32, activation=\"relu\")(inputs)\noutputs = tf.keras.layers.Dense(1, activation=\"sigmoid\")(branch_a)\nmodel = tf.keras.Model(inputs=inputs, outputs=outputs)","question":"branch_b is built but never used. Which line should have combined it with branch_a before the output layer?"}'::jsonb, '{"requiredLineIds":["outputs = tf.keras.layers.Dense(1, activation=\"sigmoid\")(branch_a)"]}'::jsonb),
  ('mission-ai-tensorflow-engine-04-o2-c1', 'mission-ai-tensorflow-engine-04-o2', 1, 'multiple_choice', 'What does tf.keras.Input(shape=(20,)) actually create?', '{"question":"What does tf.keras.Input(shape=(20,)) actually create?","options":[{"id":"a","text":"A placeholder tensor describing the expected input shape, used to build a graph of layers"},{"id":"b","text":"An already-loaded dataset with 20 rows"},{"id":"c","text":"A trained input layer with real weights"},{"id":"d","text":"A callback that runs before training starts"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),

  ('mission-ai-tensorflow-engine-05-o1-c1', 'mission-ai-tensorflow-engine-05-o1', 1, 'code_debugging', 'This tf.data pipeline batches before shuffling. Find the line that needs to move earlier.', '{"language":"python","code":"dataset = tf.data.Dataset.from_tensor_slices((features, labels))\ndataset = dataset.batch(32)\ndataset = dataset.shuffle(buffer_size=1000)\ndataset = dataset.prefetch(tf.data.AUTOTUNE)","question":"Batching before shuffling only shuffles the order of whole batches, not individual examples. Which line is out of order?"}'::jsonb, '{"requiredLineIds":["dataset = dataset.shuffle(buffer_size=1000)"]}'::jsonb),
  ('mission-ai-tensorflow-engine-05-o2-c1', 'mission-ai-tensorflow-engine-05-o2', 1, 'multiple_choice', 'What does .prefetch(tf.data.AUTOTUNE) actually do?', '{"question":"What does .prefetch(tf.data.AUTOTUNE) actually do?","options":[{"id":"a","text":"Shuffles the dataset randomly"},{"id":"b","text":"Prepares the next batch while the current batch trains, overlapping data loading with computation"},{"id":"c","text":"Reduces the batch size automatically when memory is low"},{"id":"d","text":"Fixes the order examples were shuffled in"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-tensorflow-engine-06-o1-c1', 'mission-ai-tensorflow-engine-06-o1', 1, 'multiple_choice', '10-class classification with plain integer labels, not one-hot vectors. Which loss fits?', '{"question":"10-class classification with plain integer labels (0 through 9, not one-hot vectors). Which loss fits?","options":[{"id":"a","text":"MeanSquaredError"},{"id":"b","text":"BinaryCrossentropy"},{"id":"c","text":"SparseCategoricalCrossentropy"},{"id":"d","text":"Hinge"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),
  ('mission-ai-tensorflow-engine-06-o2-c1', 'mission-ai-tensorflow-engine-06-o2', 1, 'code_debugging', 'Find the line that uses the wrong loss for these labels.', '{"language":"python","code":"model.compile(\n    optimizer=\"adam\",\n    loss=tf.keras.losses.CategoricalCrossentropy(),\n    metrics=[\"accuracy\"],\n)\nmodel.fit(train_dataset, epochs=10)","question":"train_dataset yields labels as plain integers, not one-hot vectors. Which line uses the wrong loss for that?"}'::jsonb, '{"requiredLineIds":["    loss=tf.keras.losses.CategoricalCrossentropy(),"]}'::jsonb),

  ('mission-ai-tensorflow-engine-07-o1-c1', 'mission-ai-tensorflow-engine-07-o1', 1, 'multiple_choice', 'What does an optimizer actually control during training?', '{"question":"What does an optimizer actually control during training?","options":[{"id":"a","text":"How the weights of a model get updated, based on the gradients computed from the loss"},{"id":"b","text":"Which loss function gets used"},{"id":"c","text":"How the dataset gets batched"},{"id":"d","text":"Which layer runs first in the network"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-ai-tensorflow-engine-07-o2-c1', 'mission-ai-tensorflow-engine-07-o2', 1, 'multiple_choice', 'A model trained with Adam at a learning rate of 0.5 has a loss that oscillates wildly and never settles. What is the most likely fix?', '{"question":"A model trained with Adam at a learning rate of 0.5 has a loss that oscillates wildly and never settles. What is the most likely fix?","options":[{"id":"a","text":"Increase the learning rate further"},{"id":"b","text":"Lower the learning rate"},{"id":"c","text":"Add more hidden layers"},{"id":"d","text":"Remove the loss function entirely"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-tensorflow-engine-08-o1-c1', 'mission-ai-tensorflow-engine-08-o1', 1, 'multiple_choice', 'What is the key difference between a loss function and a metric?', '{"question":"What is the key difference between a loss function and a metric?","options":[{"id":"a","text":"There is no real difference between them"},{"id":"b","text":"The loss drives gradient-based optimization and must be differentiable; metrics exist for monitoring and do not need to be"},{"id":"c","text":"Metrics are always more accurate than losses"},{"id":"d","text":"A loss is optional but a metric is required"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-tensorflow-engine-08-o2-c1', 'mission-ai-tensorflow-engine-08-o2', 1, 'drag_and_drop', 'Match each classification metric to what it actually measures.', '{"items":[{"id":"i1","text":"Accuracy"},{"id":"i2","text":"Precision"},{"id":"i3","text":"Recall"},{"id":"i4","text":"AUC"}],"targets":[{"id":"t1","label":"Fraction of all predictions that were correct"},{"id":"t2","label":"Of everything predicted positive, the fraction that was actually positive"},{"id":"t3","label":"Of everything actually positive, the fraction the model correctly caught"},{"id":"t4","label":"A threshold-independent measure of how well the model ranks positives above negatives"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3","i4":"t4"}}'::jsonb),

  ('mission-ai-tensorflow-engine-09-o1-c1', 'mission-ai-tensorflow-engine-09-o1', 1, 'code_debugging', 'This EarlyStopping configuration defeats its own purpose. Find the line to fix.', '{"language":"python","code":"callbacks = [\n    tf.keras.callbacks.EarlyStopping(monitor=\"loss\", patience=3),\n]\nmodel.fit(train_ds, validation_data=val_ds, epochs=50, callbacks=callbacks)","question":"EarlyStopping is meant to stop training once the model starts overfitting. Which line undermines that?"}'::jsonb, '{"requiredLineIds":["    tf.keras.callbacks.EarlyStopping(monitor=\"loss\", patience=3),"]}'::jsonb),
  ('mission-ai-tensorflow-engine-09-o2-c1', 'mission-ai-tensorflow-engine-09-o2', 1, 'multiple_choice', 'What does patience=3 control in EarlyStopping?', '{"question":"What does patience=3 control in EarlyStopping?","options":[{"id":"a","text":"The total number of epochs to train"},{"id":"b","text":"How many epochs to wait for improvement before actually stopping"},{"id":"c","text":"The batch size used during training"},{"id":"d","text":"How much the learning rate decays each epoch"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-tensorflow-engine-10-o1-c1', 'mission-ai-tensorflow-engine-10-o1', 1, 'code_debugging', 'This checkpoint is set up to keep the worst-performing model instead of the best. Find the bug.', '{"language":"python","code":"checkpoint_cb = tf.keras.callbacks.ModelCheckpoint(\n    filepath=\"model_checkpoint.h5\",\n    monitor=\"val_accuracy\",\n    save_best_only=True,\n    mode=\"min\",\n)","question":"Higher val_accuracy is better, not lower. Which line has this backwards?"}'::jsonb, '{"requiredLineIds":["    mode=\"min\","]}'::jsonb),
  ('mission-ai-tensorflow-engine-10-o2-c1', 'mission-ai-tensorflow-engine-10-o2', 1, 'multiple_choice', 'Why checkpoint a model during a long training run instead of only saving it at the end?', '{"question":"Why checkpoint a model during a long training run instead of only saving it at the end?","options":[{"id":"a","text":"To survive a crash or interruption without losing all progress, and to keep the best-performing version even if later epochs get worse"},{"id":"b","text":"Checkpointing makes each epoch train faster"},{"id":"c","text":"Checkpointing removes the need for a validation set"},{"id":"d","text":"TensorFlow requires at least one checkpoint to run at all"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),

  ('mission-ai-tensorflow-engine-11-o1-c1', 'mission-ai-tensorflow-engine-11-o1', 1, 'code_debugging', 'This custom train_step always returns gradients of None. Find where the bug starts.', '{"language":"python","code":"def train_step(x, y):\n    predictions = model(x, training=True)\n    loss = loss_fn(y, predictions)\n    with tf.GradientTape() as tape:\n        gradients = tape.gradient(loss, model.trainable_variables)\n    optimizer.apply_gradients(zip(gradients, model.trainable_variables))\n    return loss","question":"The forward pass and loss are computed before the tape ever opens. Which line needs to move inside the tf.GradientTape block?"}'::jsonb, '{"requiredLineIds":["    predictions = model(x, training=True)"]}'::jsonb),
  ('mission-ai-tensorflow-engine-11-o2-c1', 'mission-ai-tensorflow-engine-11-o2', 1, 'multiple_choice', 'What does tf.GradientTape actually record?', '{"question":"What does tf.GradientTape actually record?","options":[{"id":"a","text":"Every line of Python code that runs, regardless of what it touches"},{"id":"b","text":"Operations involving trainable tensors, while the tape is open, so their gradients can be computed afterward"},{"id":"c","text":"Only the final loss value, nothing before it"},{"id":"d","text":"The order in which the dataset was shuffled"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-tensorflow-engine-12-o1-c1', 'mission-ai-tensorflow-engine-12-o1', 1, 'investigation', 'Which evidence confirms the TensorFlow model was actually built as a fair architectural match?', '{"evidence":[{"id":"e1","label":"Architecture log","detail":"TensorFlow model uses two hidden layers of 128 and 64 units with ReLU activations, matching the layer sizes and parameter count of the PyTorch model almost exactly"},{"id":"e2","label":"Build note","detail":"TensorFlow model was given three extra hidden layers beyond the PyTorch version, added after early results looked weak"},{"id":"e3","label":"Ops note","detail":"TensorFlow training ran on a newer GPU model than the PyTorch training run"}],"question":"Which evidence confirms the TensorFlow model was actually built as a fair architectural match, not stacked to win?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-tensorflow-engine-12-o2-c1', 'mission-ai-tensorflow-engine-12-o2', 1, 'investigation', 'Which evidence confirms the training and evaluation protocol was held constant across both frameworks?', '{"evidence":[{"id":"e1","label":"Protocol log","detail":"Same train, validation and test split generated from the same fixed random seed as the PyTorch run, same learning rate, batch size and epoch count, evaluated on the same held-out test set"},{"id":"e2","label":"Ops note","detail":"TensorFlow training happened three days after the PyTorch run, on a different physical GPU"},{"id":"e3","label":"Build note","detail":"TensorFlow model used one extra callback, early stopping, that the PyTorch run did not have configured"}],"question":"Which evidence actually confirms the training and evaluation protocol was held constant across both frameworks?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-tensorflow-engine-12-o3-c1', 'mission-ai-tensorflow-engine-12-o3', 1, 'investigation', 'With both models performing equivalently, which evidence should actually decide the framework standardization call?', '{"evidence":[{"id":"e1","label":"Platform note","detail":"The deployment target already runs TensorFlow Serving in production for two other Cipher Labs systems, and most engineers across Cipher Division have hands-on TensorFlow deployment experience"},{"id":"e2","label":"Benchmark log","detail":"TensorFlow model scored 0.3 percent higher raw accuracy than the PyTorch model on this run, well within normal run-to-run noise"},{"id":"e3","label":"Style log","detail":"A linting report shows the TensorFlow code uses two more blank lines per file than the PyTorch code"}],"question":"With both models performing equivalently, which evidence should actually decide which framework Cipher Division standardizes on?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-tensorflow-engine-12-o4-c1', 'mission-ai-tensorflow-engine-12-o4', 1, 'boss_encounter', 'Having judged the build, the protocol, and the real deciding factor, state Cipher Division''s verdict.', '{"stages":[{"objectiveRef":"mission-ai-tensorflow-engine-12-o1","label":"Confirm a fair build"},{"objectiveRef":"mission-ai-tensorflow-engine-12-o2","label":"Confirm a fair protocol"},{"objectiveRef":"mission-ai-tensorflow-engine-12-o3","label":"Name the real deciding factor"}],"task":"State the verdict: are the two frameworks functionally equivalent for this task under a fair comparison, and what should actually decide which one Cipher Division standardizes on?"}'::jsonb, '{"requiredObjectiveIds":["mission-ai-tensorflow-engine-12-o1","mission-ai-tensorflow-engine-12-o2","mission-ai-tensorflow-engine-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-ai-tensorflow-engine-01-o1-c1', 'orientation', 'There is nothing to solve here -- just confirm you are ready to start with Noah.', 0, 1),

  ('mission-ai-tensorflow-engine-01-o2-c1', 'orientation', 'Ask which TensorFlow type is meant to change during training, and which one never does.', 10, 1),
  ('mission-ai-tensorflow-engine-01-o2-c1', 'concept', 'tf.Variable is the trainable TensorFlow tensor type, tracked automatically for gradients. tf.constant never changes.', 20, 2),
  ('mission-ai-tensorflow-engine-01-o2-c1', 'solution', 'torch.tensor maps to tf.constant, a tensor with requires_grad=True maps to tf.Variable(trainable=True), zeros_like keeps the same name in both, and .numpy() is spelled identically in both frameworks.', 30, 3),

  ('mission-ai-tensorflow-engine-02-o1-c1', 'orientation', 'Compare this relationship to one Cipher Division already knows from PyTorch Forge -- torch.nn sitting on top of raw tensors.', 10, 1),
  ('mission-ai-tensorflow-engine-02-o1-c1', 'solution', 'Keras is the high-level API built into TensorFlow for defining, training and evaluating models -- not a separate or competing framework.', 20, 2),
  ('mission-ai-tensorflow-engine-02-o2-c1', 'orientation', 'Dense takes a unit count first, then an activation keyword -- neither one is about training configuration.', 10, 1),
  ('mission-ai-tensorflow-engine-02-o2-c1', 'solution', 'Dense(64, activation="relu") sets this layer to 64 neurons using a ReLU activation. Optimizer and loss are configured separately, in compile().', 20, 2),

  ('mission-ai-tensorflow-engine-03-o1-c1', 'orientation', 'Look at the very last layer -- the one responsible for the model output.', 10, 1),
  ('mission-ai-tensorflow-engine-03-o1-c1', 'concept', 'ReLU outputs are unbounded and can all be nonzero at once. A 10-class probability distribution needs values between 0 and 1 that sum to 1.', 20, 2),
  ('mission-ai-tensorflow-engine-03-o1-c1', 'solution', 'The final Dense(10, ...) layer uses activation="relu" instead of activation="softmax". Softmax is what turns raw scores into a valid probability distribution across the 10 classes.', 30, 3),
  ('mission-ai-tensorflow-engine-03-o2-c1', 'orientation', 'Sequential can only ever pass one tensor forward, one layer at a time, in a straight line.', 10, 1),
  ('mission-ai-tensorflow-engine-03-o2-c1', 'solution', 'Sequential cannot express multiple inputs, multiple outputs, or a layer reused in two places. That is exactly what the Functional API adds.', 20, 2),

  ('mission-ai-tensorflow-engine-04-o1-c1', 'orientation', 'branch_a and branch_b both start from inputs, but only one of them ever reaches the output layer.', 10, 1),
  ('mission-ai-tensorflow-engine-04-o1-c1', 'concept', 'In the Functional API, combining two branches usually means passing both of them into a layer like tf.keras.layers.Concatenate() before continuing forward.', 20, 2),
  ('mission-ai-tensorflow-engine-04-o1-c1', 'solution', 'The outputs line only calls the output layer on branch_a. It needed to combine branch_a and branch_b first, for example outputs = tf.keras.layers.Dense(1, activation="sigmoid")(tf.keras.layers.Concatenate()([branch_a, branch_b])).', 30, 3),
  ('mission-ai-tensorflow-engine-04-o2-c1', 'orientation', 'Nothing has been computed yet at this point -- no data has been loaded, no weights exist.', 10, 1),
  ('mission-ai-tensorflow-engine-04-o2-c1', 'solution', 'tf.keras.Input(shape=(20,)) only creates a placeholder tensor describing the shape of data the model will eventually receive, used to start building the layer graph.', 20, 2),

  ('mission-ai-tensorflow-engine-05-o1-c1', 'orientation', 'Think about what unit gets shuffled if shuffle runs after batch has already grouped examples together.', 10, 1),
  ('mission-ai-tensorflow-engine-05-o1-c1', 'concept', 'shuffle() reorders whatever elements currently exist in the dataset. After batch(), those elements are already whole batches, not individual examples.', 20, 2),
  ('mission-ai-tensorflow-engine-05-o1-c1', 'solution', 'dataset.shuffle(buffer_size=1000) needs to run before dataset.batch(32), so individual examples get shuffled first and batches are then assembled from that shuffled order.', 30, 3),
  ('mission-ai-tensorflow-engine-05-o2-c1', 'orientation', 'Training and data loading are two separate pieces of work that do not have to happen strictly one after another.', 10, 1),
  ('mission-ai-tensorflow-engine-05-o2-c1', 'solution', 'prefetch overlaps preparation of the next batch with training on the current one, so the model spends less time waiting on data.', 20, 2),

  ('mission-ai-tensorflow-engine-06-o1-c1', 'orientation', 'Match the label format -- one-hot vectors versus plain integers -- to the loss variant built for it.', 10, 1),
  ('mission-ai-tensorflow-engine-06-o1-c1', 'solution', 'SparseCategoricalCrossentropy is built exactly for integer class labels. CategoricalCrossentropy expects one-hot vectors instead.', 20, 2),
  ('mission-ai-tensorflow-engine-06-o2-c1', 'orientation', 'Check what format the labels are actually in before trusting the loss that was chosen.', 10, 1),
  ('mission-ai-tensorflow-engine-06-o2-c1', 'concept', 'CategoricalCrossentropy assumes each label is already a one-hot vector. Feed it plain integers and the loss computes something meaningless.', 20, 2),
  ('mission-ai-tensorflow-engine-06-o2-c1', 'solution', 'The loss=tf.keras.losses.CategoricalCrossentropy() line is wrong for integer labels. It should be tf.keras.losses.SparseCategoricalCrossentropy().', 30, 3),

  ('mission-ai-tensorflow-engine-07-o1-c1', 'orientation', 'The loss measures how wrong the model is. Something else has to decide what to do about that number.', 10, 1),
  ('mission-ai-tensorflow-engine-07-o1-c1', 'solution', 'The optimizer updates the weights of the model using the gradients computed from the loss -- that update rule is the entire job of an optimizer.', 20, 2),
  ('mission-ai-tensorflow-engine-07-o2-c1', 'orientation', 'A learning rate that is too large makes each update overshoot, bouncing past a good solution instead of settling into one.', 10, 1),
  ('mission-ai-tensorflow-engine-07-o2-c1', 'solution', 'Lowering the learning rate is the most likely fix. At 0.5, updates are almost certainly too large, causing the loss to overshoot and oscillate instead of converging.', 20, 2),

  ('mission-ai-tensorflow-engine-08-o1-c1', 'orientation', 'Ask which of the two has to be differentiable for gradient descent to even work.', 10, 1),
  ('mission-ai-tensorflow-engine-08-o1-c1', 'solution', 'Loss drives the actual gradient-based optimization and must be differentiable. Metrics like accuracy exist purely so a human can monitor training and do not need that property.', 20, 2),
  ('mission-ai-tensorflow-engine-08-o2-c1', 'orientation', 'Two of these care about predicted positives, one cares about actual positives, and one cares about ranking quality overall.', 10, 1),
  ('mission-ai-tensorflow-engine-08-o2-c1', 'solution', 'Accuracy: fraction of all predictions correct. Precision: of predicted positives, fraction actually positive. Recall: of actual positives, fraction caught. AUC: how well the model ranks positives above negatives, independent of threshold.', 20, 2),

  ('mission-ai-tensorflow-engine-09-o1-c1', 'orientation', 'Training loss and validation loss tell very different stories once a model starts overfitting.', 10, 1),
  ('mission-ai-tensorflow-engine-09-o1-c1', 'concept', 'Training loss can keep improving long after the model has stopped generalizing to new data. Only validation loss reflects that.', 20, 2),
  ('mission-ai-tensorflow-engine-09-o1-c1', 'solution', 'monitor="loss" watches training loss, which defeats the purpose. It should be monitor="val_loss", so EarlyStopping actually reacts to overfitting.', 30, 3),
  ('mission-ai-tensorflow-engine-09-o2-c1', 'orientation', 'Patience is about tolerance for a lack of improvement, not about total training length.', 10, 1),
  ('mission-ai-tensorflow-engine-09-o2-c1', 'solution', 'patience=3 means EarlyStopping waits 3 epochs without improvement in the monitored value before it actually stops training.', 20, 2),

  ('mission-ai-tensorflow-engine-10-o1-c1', 'orientation', 'mode tells ModelCheckpoint which direction counts as an improvement for the metric being monitored.', 10, 1),
  ('mission-ai-tensorflow-engine-10-o1-c1', 'concept', 'val_accuracy improves as it goes up, not down. mode="min" tells the callback to treat the lowest accuracy as the best one.', 20, 2),
  ('mission-ai-tensorflow-engine-10-o1-c1', 'solution', 'mode="min" is backwards for val_accuracy. It should be mode="max", so the checkpoint keeps the epoch with the highest validation accuracy.', 30, 3),
  ('mission-ai-tensorflow-engine-10-o2-c1', 'orientation', 'Think about what happens to a long run if the process is interrupted halfway through, or if the model gets worse in its final epochs.', 10, 1),
  ('mission-ai-tensorflow-engine-10-o2-c1', 'solution', 'Checkpoints protect against crashes or interruptions losing all progress, and against the final epoch not actually being the best one -- save_best_only keeps the strongest version regardless of what happens after it.', 20, 2),

  ('mission-ai-tensorflow-engine-11-o1-c1', 'orientation', 'GradientTape can only record operations that happen while it is open. Anything computed before it opens is invisible to it.', 10, 1),
  ('mission-ai-tensorflow-engine-11-o1-c1', 'concept', 'predictions and loss are both computed above the with tf.GradientTape() as tape: line, so the tape never sees the forward pass at all.', 20, 2),
  ('mission-ai-tensorflow-engine-11-o1-c1', 'solution', 'predictions = model(x, training=True) and loss = loss_fn(y, predictions) both need to move inside the with tf.GradientTape() as tape: block, so the tape actually records the operations it needs gradients for.', 30, 3),
  ('mission-ai-tensorflow-engine-11-o2-c1', 'orientation', 'The tape is not a general code logger. It only cares about tensors it can compute gradients through.', 10, 1),
  ('mission-ai-tensorflow-engine-11-o2-c1', 'solution', 'tf.GradientTape records operations involving trainable tensors for as long as it stays open, so tape.gradient() can later compute how the loss depends on each one.', 20, 2),

  ('mission-ai-tensorflow-engine-12-o1-c1', 'orientation', 'Weigh the evidence about what was actually built, not how confident anyone sounds about it.', 10, 1),
  ('mission-ai-tensorflow-engine-12-o1-c1', 'solution', 'e1: matching layer sizes and parameter count almost exactly is what a fair architectural match looks like. e2 describes the opposite -- an unfair advantage that did not actually happen here.', 20, 2),

  ('mission-ai-tensorflow-engine-12-o2-c1', 'orientation', 'A fair comparison depends on what stayed identical between the two runs, not on when or where each one happened.', 10, 1),
  ('mission-ai-tensorflow-engine-12-o2-c1', 'solution', 'e1: identical splits from the same seed, matching hyperparameters, and the same held-out test set is what a controlled protocol looks like. Timing and GPU model do not affect fairness.', 20, 2),

  ('mission-ai-tensorflow-engine-12-o3-c1', 'orientation', 'Accuracy is already equivalent between the two models -- that is the whole point of this comparison. The deciding factor has to be something else.', 10, 1),
  ('mission-ai-tensorflow-engine-12-o3-c1', 'solution', 'e1: existing production infrastructure and team experience both point toward one framework -- that is what should decide a standardization call once performance is already a tie.', 20, 2),

  ('mission-ai-tensorflow-engine-12-o4-c1', 'orientation', 'Look at what confirming the build, the protocol, and the deciding factor all proved together, not as separate facts.', 15, 1),
  ('mission-ai-tensorflow-engine-12-o4-c1', 'solution', 'The TensorFlow and PyTorch models are functionally equivalent for this task under a fair comparison. The real decision comes down to team familiarity, deployment target, and existing ecosystem, not accuracy.', 25, 2);
